import { useState, useCallback, useEffect, useMemo, useRef } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel, PendingQuestion, FailedQuestion, ExchangeSelection } from './components/QuestionPanel';
import { DocumentDetail, ChunkFocus } from './components/DocumentDetail';
import { ConversationHistory } from './components/ConversationHistory';
import { StatusBar } from './components/StatusBar';
import { Document, AppStatus, ConversationExchange } from '../shared/types';
import { formatIpcError } from './format';

const tabStyle = (active: boolean) => ({
  flex: 1,
  padding: '8px',
  background: active ? '#0f3460' : 'transparent',
  color: active ? '#e0e0e0' : '#9a9ac0',
  border: 'none',
  borderBottom: active ? '2px solid #533483' : '2px solid transparent',
  cursor: 'pointer',
  fontSize: '12px',
  fontWeight: 500,
});

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [conversation, setConversation] = useState<ConversationExchange[]>([]);
  const [historyError, setHistoryError] = useState<string | null>(null);
  const [pending, setPending] = useState<PendingQuestion | null>(null);
  const [failed, setFailed] = useState<FailedQuestion | null>(null);
  const [selection, setSelection] = useState<ExchangeSelection | null>(null);
  const [activeTab, setActiveTab] = useState<'documents' | 'conversation'>('documents');
  const [chunkFocus, setChunkFocus] = useState<ChunkFocus | null>(null);
  const [now, setNow] = useState(() => new Date());
  /** Bumped on every clear so answers/errors for questions asked before it are ignored. */
  const clearEpoch = useRef(0);

  // Re-render relative timestamps ("Today", "Yesterday") just after each midnight.
  useEffect(() => {
    const nextMidnight = new Date(now);
    nextMidnight.setHours(24, 0, 1, 0);
    const timer = window.setTimeout(() => setNow(new Date()), nextMidnight.getTime() - Date.now());
    return () => window.clearTimeout(timer);
  }, [now]);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  const refreshConversation = useCallback(async () => {
    try {
      setConversation(await window.knowledgeBase.conversation.get());
      setHistoryError(null);
    } catch (err) {
      // Never keep showing an old conversation as if it were current.
      setConversation([]);
      setSelection(null);
      setHistoryError(formatIpcError(err));
    }
  }, []);

  const refreshAll = useCallback(() => {
    refreshDocuments();
    refreshConversation();
  }, [refreshDocuments, refreshConversation]);

  useEffect(refreshAll, [refreshAll]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleAskQuestion = useCallback(async (question: string, followUpOf: string | null) => {
    const epoch = clearEpoch.current;
    setFailed(null);
    setPending({ question, followUpOf });
    try {
      await window.knowledgeBase.qa.ask(question, followUpOf ?? undefined);
      if (epoch === clearEpoch.current) await refreshConversation();
    } catch (err) {
      if (epoch === clearEpoch.current) setFailed({ question, followUpOf, message: formatIpcError(err) });
    } finally {
      // A clear discards the pending question (the service does not save its answer).
      if (epoch === clearEpoch.current) setPending(null);
    }
  }, [refreshConversation]);

  const handleRetry = useCallback(() => {
    if (failed) handleAskQuestion(failed.question, failed.followUpOf);
  }, [failed, handleAskQuestion]);

  const handleClearConversation = useCallback(async () => {
    clearEpoch.current++;
    setPending(null);
    try {
      await window.knowledgeBase.qa.clearHistory();
      setFailed(null);
      setSelection(null);
    } catch (err) {
      setHistoryError(formatIpcError(err));
    }
    await refreshConversation();
  }, [refreshConversation]);

  const documentIds = useMemo(() => new Set(documents.map(d => d.id)), [documents]);
  const isDocumentAvailable = useCallback((id: string) => documentIds.has(id), [documentIds]);

  const handleOpenCitation = useCallback((documentId: string, chunkIndex: number) => {
    const doc = documents.find(d => d.id === documentId);
    if (!doc) return;
    setSelectedDoc(doc);
    setChunkFocus(prev => ({ documentId, index: chunkIndex, seq: (prev?.seq ?? 0) + 1 }));
  }, [documents]);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
    setChunkFocus(null);
  }, []);

  const handleSelectExchange = useCallback((exchangeId: string) => {
    setSelection(prev => ({ id: exchangeId, seq: (prev?.seq ?? 0) + 1 }));
  }, []);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <button
          type="button"
          onClick={refreshAll}
          style={{
            padding: '6px 14px',
            background: '#0f3460',
            color: '#e0e0e0',
            border: '1px solid #1a1a4e',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '13px',
          }}
        >
          Refresh
        </button>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list + question history index */}
        <aside style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{ display: 'flex', borderBottom: '1px solid #0f3460' }}>
            <button
              type="button"
              aria-pressed={activeTab === 'documents'}
              onClick={() => setActiveTab('documents')}
              style={tabStyle(activeTab === 'documents')}
            >
              Documents ({documents.length})
            </button>
            <button
              type="button"
              aria-pressed={activeTab === 'conversation'}
              onClick={() => setActiveTab('conversation')}
              style={tabStyle(activeTab === 'conversation')}
            >
              History ({conversation.length})
            </button>
          </div>
          {activeTab === 'documents' ? (
            <>
              <div style={{
                padding: '6px 16px',
                display: 'flex',
                justifyContent: 'flex-end',
              }}>
                <button
                  type="button"
                  onClick={handleImport}
                  style={{
                    padding: '4px 10px',
                    background: '#533483',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '3px',
                    cursor: 'pointer',
                    fontSize: '12px',
                  }}
                >
                  + Import
                </button>
              </div>
              <DocumentList
                documents={documents}
                onSelect={handleSelectDocument}
                selectedId={selectedDoc?.id ?? null}
              />
            </>
          ) : (
            <ConversationHistory
              conversation={conversation}
              selectedId={selection?.id ?? null}
              now={now}
              onSelect={handleSelectExchange}
            />
          )}
        </aside>

        {/* Right panel: optional document detail above the conversation */}
        <main style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          {selectedDoc && (
            <section
              aria-label="Document detail"
              style={{ maxHeight: '45%', overflow: 'auto', padding: '16px 20px', borderBottom: '1px solid #0f3460', position: 'relative' }}
            >
              <button
                type="button"
                onClick={() => setSelectedDoc(null)}
                aria-label={`Close document ${selectedDoc.title}`}
                style={{
                  position: 'absolute',
                  top: '12px',
                  right: '16px',
                  padding: '3px 10px',
                  background: 'transparent',
                  color: '#c0c0e0',
                  border: '1px solid #2a3a6e',
                  borderRadius: '4px',
                  cursor: 'pointer',
                  fontSize: '12px',
                }}
              >
                Close
              </button>
              <DocumentDetail
                document={selectedDoc}
                focus={chunkFocus?.documentId === selectedDoc.id ? chunkFocus : null}
              />
            </section>
          )}

          <QuestionPanel
            conversation={conversation}
            historyError={historyError}
            pending={pending}
            failed={failed}
            selection={selection}
            now={now}
            isDocumentAvailable={isDocumentAvailable}
            onAsk={handleAskQuestion}
            onRetry={handleRetry}
            onDismissError={() => setFailed(null)}
            onClear={handleClearConversation}
            onOpenCitation={handleOpenCitation}
            onSelectExchange={handleSelectExchange}
          />
        </main>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}
import { useEffect, useMemo, useRef, useState, type FormEvent, type KeyboardEvent } from 'react';
import { ConversationExchange } from '../../shared/types';
import { ExchangeItem } from './ExchangeItem';
import { errorBox, metaText, smallButton, userBubble } from '../styles';

export interface PendingQuestion {
  question: string;
  followUpOf: string | null;
}

export interface FailedQuestion extends PendingQuestion {
  message: string;
}

/** A request to scroll to and highlight an exchange; `seq` lets the same exchange be selected twice. */
export interface ExchangeSelection {
  id: string;
  seq: number;
}

interface Props {
  conversation: ConversationExchange[];
  historyError: string | null;
  pending: PendingQuestion | null;
  failed: FailedQuestion | null;
  selection: ExchangeSelection | null;
  now: Date;
  isDocumentAvailable: (documentId: string) => boolean;
  onAsk: (question: string, followUpOf: string | null) => void;
  onRetry: () => void;
  onDismissError: () => void;
  onClear: () => Promise<void>;
  onOpenCitation: (documentId: string, chunkIndex: number) => void;
  onSelectExchange: (exchangeId: string) => void;
}

export function QuestionPanel({
  conversation,
  historyError,
  pending,
  failed,
  selection,
  now,
  isDocumentAvailable,
  onAsk,
  onRetry,
  onDismissError,
  onClear,
  onOpenCitation,
  onSelectExchange,
}: Props) {
  const [question, setQuestion] = useState('');
  const [followUpId, setFollowUpId] = useState<string | null>(null);
  const [confirmingClear, setConfirmingClear] = useState(false);
  const [highlightedId, setHighlightedId] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const threadEndRef = useRef<HTMLDivElement>(null);
  const clearButtonRef = useRef<HTMLButtonElement>(null);
  /** Set when the confirmation is cancelled so focus returns to "Clear conversation" once it is back. */
  const restoreClearFocus = useRef(false);

  useEffect(() => {
    if (!confirmingClear && restoreClearFocus.current) {
      restoreClearFocus.current = false;
      clearButtonRef.current?.focus();
    }
  }, [confirmingClear]);

  const byId = useMemo(() => new Map(conversation.map(e => [e.id, e])), [conversation]);
  // A follow-up target that disappeared (e.g. history cleared) is silently dropped.
  const followUpTarget = followUpId ? byId.get(followUpId) ?? null : null;

  // Keep the newest exchange, pending question or error in view.
  useEffect(() => {
    threadEndRef.current?.scrollIntoView({ block: 'end' });
  }, [conversation.length, pending, failed]);

  // Scroll to, focus and briefly highlight an exchange selected elsewhere.
  useEffect(() => {
    if (!selection) return;
    const el = document.getElementById(`exchange-${selection.id}`);
    if (!el) return;
    el.scrollIntoView({ block: 'start' });
    el.focus({ preventScroll: true });
    setHighlightedId(selection.id);
    const timer = window.setTimeout(() => setHighlightedId(null), 1600);
    return () => window.clearTimeout(timer);
  }, [selection]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = question.trim();
    if (!trimmed || pending) return;
    onAsk(trimmed, followUpTarget?.id ?? null);
    setQuestion('');
    setFollowUpId(null);
  };

  const startFollowUp = (exchange: ConversationExchange) => {
    setFollowUpId(exchange.id);
    inputRef.current?.focus();
  };

  const cancelClear = () => {
    restoreClearFocus.current = true;
    setConfirmingClear(false);
  };

  const handleConfirmKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      cancelClear();
    }
  };

  const confirmClear = async () => {
    setConfirmingClear(false);
    setFollowUpId(null);
    await onClear();
    inputRef.current?.focus();
  };

  const isEmpty = conversation.length === 0 && !pending && !failed;

  return (
    <section aria-labelledby="conversation-heading" style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          padding: '8px 20px',
          borderBottom: '1px solid #0f3460',
          minHeight: '42px',
        }}
      >
        <h2 id="conversation-heading" style={{ fontSize: '14px', fontWeight: 600 }}>
          Conversation{' '}
          <span style={{ ...metaText, fontWeight: 400 }}>
            ({conversation.length} {conversation.length === 1 ? 'exchange' : 'exchanges'})
          </span>
        </h2>
        {conversation.length > 0 &&
          (confirmingClear ? (
            <div
              role="group"
              aria-label="Confirm clearing the conversation"
              onKeyDown={handleConfirmKeyDown}
              style={{ display: 'flex', gap: '6px', alignItems: 'center' }}
            >
              <span style={{ fontSize: '12px' }}>
                Delete all {conversation.length} {conversation.length === 1 ? 'exchange' : 'exchanges'}
                {pending ? ' and discard the question still being answered' : ''}?
              </span>
              <button type="button" onClick={confirmClear} style={{ ...smallButton, background: '#8b2635', borderColor: '#8b2635', color: '#fff' }}>
                Clear
              </button>
              <button type="button" onClick={cancelClear} style={smallButton} autoFocus>
                Cancel
              </button>
            </div>
          ) : (
            <button type="button" ref={clearButtonRef} onClick={() => setConfirmingClear(true)} style={smallButton}>
              Clear conversation
            </button>
          ))}
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: '12px 20px' }}>
        {historyError && (
          <div style={{ color: '#888', textAlign: 'center', paddingTop: '40px', fontSize: '14px' }}>
            The conversation could not be loaded. See the message above the question box.
          </div>
        )}

        {isEmpty && !historyError && (
          <div style={{ color: '#888', textAlign: 'center', paddingTop: '40px', fontSize: '14px', lineHeight: 1.6 }}>
            No questions yet.
            <br />
            <span style={{ fontSize: '12px' }}>
              Ask a question below — answers cite the indexed documents they are based on, and the whole conversation stays here.
            </span>
          </div>
        )}

        {/* role="log" sits on a wrapper so the <ol>/<li> keep their list semantics. */}
        <div role="log" aria-label="Questions and answers" aria-live="polite" aria-relevant="additions">
        <ol
          aria-label="Exchanges"
          style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '12px' }}
        >
          {conversation.map(exchange => (
            <li key={exchange.id}>
              <ExchangeItem
                exchange={exchange}
                parent={exchange.followUpOf ? byId.get(exchange.followUpOf) ?? null : null}
                highlighted={highlightedId === exchange.id}
                now={now}
                isDocumentAvailable={isDocumentAvailable}
                onOpenCitation={onOpenCitation}
                onFollowUp={startFollowUp}
                onJumpTo={onSelectExchange}
              />
            </li>
          ))}

          {pending && (
            <li aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '8px' }}>
              <div style={userBubble}>{pending.question}</div>
              <div style={{ ...metaText, alignSelf: 'flex-start', fontSize: '13px' }}>Assistant is searching your documents…</div>
            </li>
          )}

          {failed && (
            <li style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '8px' }}>
              <div style={userBubble}>{failed.question}</div>
              <div role="alert" style={{ ...errorBox, alignSelf: 'flex-start', maxWidth: '88%' }}>
                <div>The question could not be answered: {failed.message}</div>
                <div style={{ display: 'flex', gap: '6px', marginTop: '8px' }}>
                  <button type="button" onClick={onRetry} style={smallButton}>Retry</button>
                  <button type="button" onClick={onDismissError} style={smallButton}>Dismiss</button>
                </div>
              </div>
            </li>
          )}
        </ol>
        </div>
        <div ref={threadEndRef} />
      </div>

      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '6px',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        {historyError && (
          <div role="alert" style={errorBox}>
            Could not load the conversation history. {historyError}
          </div>
        )}
        {followUpTarget && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12px', color: '#c0c0e0' }}>
            <span id="follow-up-context" style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              ↪ Following up on “{followUpTarget.question}”
            </span>
            <button
              type="button"
              onClick={() => {
                setFollowUpId(null);
                inputRef.current?.focus();
              }}
              style={smallButton}
              aria-label="Cancel follow-up"
            >
              ✕
            </button>
          </div>
        )}
        <div style={{ display: 'flex' }}>
          <label htmlFor="question-input" className="visually-hidden">
            Ask a question about your documents
          </label>
          <input
            id="question-input"
            ref={inputRef}
            type="text"
            value={question}
            onChange={e => setQuestion(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Escape' && followUpTarget) {
                e.preventDefault();
                setFollowUpId(null);
              }
            }}
            aria-describedby={followUpTarget ? 'follow-up-context' : undefined}
            placeholder={followUpTarget ? 'Ask a follow-up question… (Esc to cancel)' : 'Ask a question about your documents...'}
            style={{
              flex: 1,
              padding: '10px 14px',
              background: '#1a1a2e',
              color: '#e0e0e0',
              border: '1px solid #0f3460',
              borderRadius: '6px',
              fontSize: '14px',
            }}
          />
          <button
            type="submit"
            disabled={!question.trim() || pending !== null}
            style={{
              marginLeft: '10px',
              padding: '10px 20px',
              background: '#533483',
              color: '#fff',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '14px',
              fontWeight: 500,
            }}
          >
            {pending ? 'Asking…' : 'Ask'}
          </button>
        </div>
      </form>
    </section>
  );
}

