const chunkElementId = (documentId: string, index: number) => `chunk-${documentId}-${index}`;

export function DocumentDetail({ document, focus = null }: Props) {
  const [loaded, setLoaded] = useState<{ documentId: string; chunks: Chunk[] } | null>(null);
  const [showChunks, setShowChunks] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    window.knowledgeBase.indexing.chunks(document.id).then(chunks => {
      if (!cancelled) setLoaded({ documentId: document.id, chunks });
    });
    return () => { cancelled = true; };
  }, [document.id]);

  const chunks = loaded?.documentId === document.id ? loaded.chunks : [];
  const chunksReady = loaded?.documentId === document.id;

  // A citation was opened: reveal the chunk list and mark the cited chunk.
  useEffect(() => {
    if (!focus) {
      setHighlightedIndex(null);
      return;
    }
    setShowChunks(true);
    setHighlightedIndex(focus.index);
  }, [focus]);

