        <blockquote
          title={excerpt}
          style={{
            margin: '4px 0 0',
            color: '#b0b0d0',
            whiteSpace: 'normal',
            overflowWrap: 'anywhere',
            lineHeight: 1.45,
            display: '-webkit-box',
            WebkitLineClamp: 3,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
          }}
        >
          {excerpt}
        </blockquote>
      )}
    </li>
  );
}

