            padding: '6px 12px',
            background: '#0f3460',
            color: '#e0e0e0',
            border: '1px solid #1a1a4e',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '12px',
          }}
        >
          {showChunks ? 'Hide' : 'Show'} Chunks ({chunks.length})
        </button>
        {document.status !== 'indexed' && (
          <button
            type="button"
            onClick={() => window.knowledgeBase.indexing.start(document.id)}
            style={{
              padding: '6px 12px',
              background: '#533483',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '12px',
            }}
          >
            Index Document
          </button>
        )}
      </div>

      {focusMissing && focus && (
        <p role="status" style={{ fontSize: '12px', color: '#f0ad4e', marginBottom: '8px' }}>
          The cited chunk {focus.index + 1} is no longer in this document's index (it may have been re-indexed).
        </p>
      )}

      {showChunks && (
        <div>
          {chunks.map(chunk => {
            const cited = chunk.index === highlightedIndex;
