                aria-current={cited ? 'true' : undefined}
                style={{
                  padding: '10px',
                  marginBottom: '8px',
                  background: cited ? 'rgba(83, 52, 131, 0.35)' : '#1a1a3e',
                  borderRadius: '4px',
                  borderLeft: cited ? '3px solid #c9b6ef' : '3px solid #533483',
                  outline: cited ? '1px solid #533483' : undefined,
                  fontSize: '13px',
                  lineHeight: 1.5,
                  whiteSpace: 'pre-wrap',
                  overflowWrap: 'anywhere',
                }}
              >
                <div style={{ fontSize: '11px', color: cited ? '#c9b6ef' : '#888', marginBottom: '4px' }}>
                  Chunk {chunk.index + 1} ({chunk.metadata.charCount} chars){cited ? ' · cited in the answer' : ''}
                </div>
                {chunk.content}
              </div>
            );
          })}
        </div>
